mapper.select:
select DU.*
from (
		select * from data_use
	   	where DEL_ID is null
	   	  	and REG_ID=#{userId}
	   		and status=#{status}
) DU
join (
		select * from data_item
	 	where DEL_ID is null
			and data_code=#{dataCode}
	 		and status=#{dataItemStatus}
) as DI on DU.data_id = DI.id

select DU.*
from (
		 select * from data_use
		 where DEL_ID is null
		   and REG_ID=#{userId}
		   and status=#{status}
	 ) DU
		 join (
	select * from data_item
	where DEL_ID is null
	  and service_id=#{serviceId}
	  and status=#{dataItemStatus}
) as DI on DU.data_id = DI.id
